-- Adds two new sub-brand logo entries to sit alongside the existing 7 on the
-- landing page hero (Eleven Australia Colour, Color.me by Kevin.Murphy).
-- These are flattened onto the hero's flat background colour rather than kept
-- transparent (source files didn't have clean transparency to begin with).
-- Safe to re-run: skips any brand that already exists by this exact name.

insert into brands (name, logo_url)
select 'Eleven Australia Colour', 'data:image/jpeg;base64,'
where not exists (select 1 from brands where name = 'Eleven Australia Colour');

insert into brands (name, logo_url)
select 'Color.me by Kevin.Murphy', 'data:image/jpeg;base64,'
where not exists (select 1 from brands where name = 'Color.me by Kevin.Murphy');
